using System;using System.IO;using System.Text;using System.Xml;using System.Linq;using System.Collections.Generic;using System.Runtime.InteropServices;
class PatchAapt {
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern IntPtr LoadLibraryEx(string file,IntPtr reserved,uint flags);
 [DllImport("kernel32.dll")]static extern bool FreeLibrary(IntPtr module);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode)]static extern IntPtr FindResource(IntPtr module,IntPtr name,IntPtr type);
 [DllImport("kernel32.dll")]static extern uint SizeofResource(IntPtr module,IntPtr resource);
 [DllImport("kernel32.dll")]static extern IntPtr LoadResource(IntPtr module,IntPtr resource);
 [DllImport("kernel32.dll")]static extern IntPtr LockResource(IntPtr resource);
 delegate bool LanguageCallback(IntPtr module,IntPtr type,IntPtr name,ushort language,IntPtr parameter);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode)]static extern bool EnumResourceLanguages(IntPtr module,IntPtr type,IntPtr name,LanguageCallback callback,IntPtr parameter);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern IntPtr BeginUpdateResource(string file,bool deleteExisting);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool UpdateResource(IntPtr update,IntPtr type,IntPtr name,ushort language,byte[] data,uint size);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool EndUpdateResource(IntPtr update,bool discard);
 static int Main(string[] args){try{string file=Path.GetFullPath(args[0]);var languages=new HashSet<ushort>();byte[] original=null;IntPtr module=LoadLibraryEx(file,IntPtr.Zero,2);if(module==IntPtr.Zero)throw new System.ComponentModel.Win32Exception();try{IntPtr resource=FindResource(module,new IntPtr(1),new IntPtr(24));if(resource!=IntPtr.Zero){uint size=SizeofResource(module,resource);original=new byte[size];Marshal.Copy(LockResource(LoadResource(module,resource)),original,0,(int)size);EnumResourceLanguages(module,new IntPtr(24),new IntPtr(1),(m,t,n,l,p)=>{languages.Add(l);return true;},IntPtr.Zero);}}finally{FreeLibrary(module);}var document=new XmlDocument{PreserveWhitespace=true};if(original!=null)using(var stream=new MemoryStream(original))document.Load(stream);else document.LoadXml("<assembly xmlns='urn:schemas-microsoft-com:asm.v1' manifestVersion='1.0'><assemblyIdentity type='win32' name='SmartTV.AaptUnicode' version='1.0.0.0'/></assembly>");var root=document.DocumentElement;var application=root.SelectSingleNode("*[local-name()='application']");if(application==null){application=document.CreateElement("application","urn:schemas-microsoft-com:asm.v3");root.AppendChild(application);}var settings=application.SelectSingleNode("*[local-name()='windowsSettings']");if(settings==null){settings=document.CreateElement("windowsSettings",application.NamespaceURI);application.AppendChild(settings);}foreach(XmlNode old in settings.SelectNodes("*[local-name()='activeCodePage']"))settings.RemoveChild(old);var codePage=document.CreateElement("activeCodePage","http://schemas.microsoft.com/SMI/2019/WindowsSettings");codePage.InnerText="UTF-8";settings.AppendChild(codePage);byte[] manifest;using(var output=new MemoryStream()){using(var writer=XmlWriter.Create(output,new XmlWriterSettings{Encoding=new UTF8Encoding(false),CloseOutput=false}))document.Save(writer);manifest=output.ToArray();}IntPtr update=BeginUpdateResource(file,false);if(update==IntPtr.Zero)throw new System.ComponentModel.Win32Exception();bool done=false;try{foreach(ushort language in languages)if(!UpdateResource(update,new IntPtr(24),new IntPtr(1),language,null,0))throw new System.ComponentModel.Win32Exception();if(!UpdateResource(update,new IntPtr(24),new IntPtr(1),0,manifest,(uint)manifest.Length))throw new System.ComponentModel.Win32Exception();if(!EndUpdateResource(update,false))throw new System.ComponentModel.Win32Exception();done=true;}finally{if(!done)EndUpdateResource(update,true);}Console.WriteLine("aapt: UTF-8 process manifest applied");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
